INSERT INTO `criterioevaluacion` (`id`, `resultado_aprendizaje_id`, `id_ref`, `letra`, `descripcion`) VALUES
(13894, 1806, 59459, 'a', 'Se han identificado los elementos estructurales de madera de una embarcación (quilla, roda, codaste, cuadernas, mamparos, entre otros) relacionándolos con su información gráfica de los planos.'),
(13895, 1806, 59460, 'b', 'Se han caracterizado los esfuerzos que soporta la estructura de una embarcación navegando y especificado la función de los elementos estructurales.'),
(13896, 1806, 59461, 'c', 'Se han relacionado los diferentes tipos de elementos estructurales con el del tipo de refuerzo que realizan.'),
(13897, 1806, 59462, 'd', 'Se ha caracterizado el proceso de trabajo empleado para reparar elementos estructurales, especificando fases, medios herramientas y materiales requeridos.'),
(13898, 1806, 59463, 'e', 'Se han relacionado las herramientas y los materiales utilizados en las operaciones de reparación de elementos estructurales con su función y uso.'),
